export const DEFAULT_MAX_RETRIES = 3;

const BASE_DELAY_MS = 2_000;
const MAX_DELAY_MS = 15 * 60_000;

/**
 * Full jitter: a uniformly random delay in [0, min(cap, base * 2^(attempt-1))].
 * `rng` must return a number in [0, 1); injectable for tests.
 */
export function backoffDelay(attempt: number, rng: () => number = Math.random): number {
  const exp = BASE_DELAY_MS * 2 ** Math.max(0, attempt - 1);
  return Math.floor(rng() * Math.min(exp, MAX_DELAY_MS));
}

export function shouldRetry(attempt: number, maxRetries = DEFAULT_MAX_RETRIES): boolean {
  return attempt < maxRetries;
}

